head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_2)은 계산식 축 : 영역별 동작과 SubTotal/Footer Column 의 계산식(집계 함수 / sumif·sumifs 조건 / targetColValue·targetColLabel)을 검증한다.
//  - Body Column 의 내장 함수 / JavaScript 표현식 / rowIndex / 다시 계산 / 미설정 / 저장되지 않음 항목은 _1(column_P_expression_1.xml) 담당.
//  - Footer 다시 계산(Cell 편집) / excludeDeletedRows·excludeModifiedRows 제외 Row 항목은 _3(column_P_expression_3.xml) 담당. (조합 수 기준 분리)
//  - 'Body/SubTotal/Footer 영역의 Column 에서 동작 ...' 검증을 위해 설정 영역 옵션(con_area : Body / SubTotal / Footer)을 둔다. (column_P_excelFormat_1 준용)
//  - description 은 @description 첫 문장 -> _1 과 동일하게 유지.
scwin.tData = {
    "description" : "[column > P > expression]<br/>inputType='expression' 인 Column 의 Cell 에 표시할 값을 산출하는 계산식을 설정합니다.",
    "validation" : [
        "Body/SubTotal/Footer 영역의 Column 에서 동작하며 영역마다 사용할 수 있는 함수와 형식이 다릅니다.",
        "문자열 설정 시, SubTotal/Footer Column 에서 사용할 수 있는 내장 함수이며 SubTotal 은 해당 그룹의 Row, Footer 는 전체 Row 를 대상으로 계산됩니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 sum('Column ID') : Column 데이터의 합계를 반환합니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 avg('Column ID') : Column 데이터의 평균값을 반환합니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 max('Column ID') : Column 데이터의 최대값을 반환합니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 min('Column ID') : Column 데이터의 최소값을 반환합니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 count('Column ID',옵션) : Column 데이터의 갯수를 반환합니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 count('Column ID',옵션) 에서 옵션을 {blank:false} 로 설정하면 빈 값('')은 세지 않습니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 sumif('Column ID','조건','조건 Column ID') : 조건 Column 의 값이 조건을 만족하는 Row 만 Column 데이터의 합계로 반환합니다.",
        "문자열 설정 시, SubTotal/Footer Column 의 sumifs('Column ID','조건1','조건1 Column ID','조건2','조건2 Column ID',...) : 모든 조건을 만족하는 Row 만 Column 데이터의 합계로 반환합니다.",
        "문자열 설정 시, SubTotal Column 에서만 사용할 수 있는 targetColValue() : SubTotal 의 targetColumnID 에 해당하는 Column 의 값을 반환합니다.",
        "문자열 설정 시, SubTotal Column 에서만 사용할 수 있는 targetColLabel() : SubTotal 의 targetColumnID 에 해당하는 Column 의 inputType='select','autoComplete','checkcombobox' 일때 Column 의 라벨값을 반환합니다.",
        "sumif() 와 sumifs() 함수의 조건은 '>', '>=', '<', '<=', '==', '!=' 연산자로 시작하는 문자열로 설정합니다.",
        "sumif() 와 sumifs() 함수의 조건에서 연산자를 생략하면 '==' 로 적용되며 '<' 문자는 그대로 쓸 수 없으므로 '&lt;' 로 작성합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_expression.setValue("sum('amount')");
    con_area.setValue("subTotal");
    con_condition.setValue(">30");
    con_inputType.setValue("select");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Column 인덱스 0:분류 1:품목 2:수량 3:금액 4:비고 5:결과. expression 은 con_area 로 고른 영역의 결과(인덱스 5) Column 에만 설정한다.
//  - SubTotal 은 분류(category) 기준이며, 분류 A(사무용품) 는 Row 0 ~ 2, B(전산장비) 는 Row 3 ~ 5 에 연속 배치한다.
//  - 계산식의 '{조건}' 은 con_condition 값으로 바꿔 설정한다. ('<' 는 XML 속성에 그대로 쓸 수 없으므로 옵션값 자체를 '&lt;' 로 작성)
//  - 비고(remark) Column 은 빈 값 Row 를 포함해 count() 의 옵션 차이를 확인한다.
//  - expression 은 dynamic N 이므로 렌더 시점에만 설정 -> 옵션 변경 후 "Target 재생성" 으로 반영
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] expression 은 선택한 영역의 결과 Column 에만 설정됨. SubTotal 은 분류 기준 (A = 사무용품 : Row 0 ~ 2, B = 전산장비 : Row 3 ~ 5)\n계산식의 {조건} 은 선택한 조건으로 바뀌어 설정됨 (조건 Column 은 수량, sumifs 의 두번째 조건은 비고 Column 의 긴급)\n[절차] 옵션 선택 -> Target 재생성 -> 결과 확인\n[확인] 선택한 영역의 결과 Cell 표시값"', '', 'label1');

    // 조건 설정
    let cExpression = con_expression.getValue().replace("{조건}", con_condition.getValue());
    let cArea = con_area.getValue();
    let cInputType = con_inputType.getValue();

    let fnResultAttr = function (sArea) {
        if (cExpression !== '' && cArea === sArea) {
            return ' inputType="expression" expression="' + cExpression + '"';
        }
        return ' inputType="text"';
    };

    // 분류 Column : select / autoComplete / checkcombobox 는 코드(A / B)와 라벨(사무용품 / 전산장비) 아이템을 갖는다.
    let strCategory = '<w2:column width="110" style="" inputType="' + cInputType + '" id="category" value="">';
    if (cInputType !== 'text') {
        strCategory += '<w2:choices>';
        strCategory += '<w2:item><w2:label>사무용품</w2:label><w2:value>A</w2:value></w2:item>';
        strCategory += '<w2:item><w2:label>전산장비</w2:label><w2:value>B</w2:value></w2:item>';
        strCategory += '</w2:choices>';
    }
    strCategory += '</w2:column>';

    // dataList 생성 (SubTotal 기준 Column 인 category 값이 같은 Row 를 연속 배치)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="category" name="category" dataType="text"></w2:column>';
    strDlt += '<w2:column id="item" name="item" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="remark" name="remark" dataType="text"></w2:column>';
    strDlt += '<w2:column id="result" name="result" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "category" : "A", "item" : "복사용지 A4", "qty" : "50", "amount" : "1250000", "remark" : "긴급", "result" : "" },
        { "category" : "A", "item" : "레이저 토너", "qty" : "30", "amount" : "2670000", "remark" : "", "result" : "" },
        { "category" : "A", "item" : "볼펜", "qty" : "200", "amount" : "160000", "remark" : "정기", "result" : "" },
        { "category" : "B", "item" : "노트북", "qty" : "10", "amount" : "14500000", "remark" : "", "result" : "" },
        { "category" : "B", "item" : "모니터", "qty" : "20", "amount" : "6400000", "remark" : "긴급", "result" : "" },
        { "category" : "B", "item" : "키보드", "qty" : "40", "amount" : "1800000", "remark" : "", "result" : "" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:640px;height:400px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hCategory" value="분류"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hItem" value="품목"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hQty" value="수량"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hAmount" value="금액"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hRemark" value="비고"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hResult" value="결과"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += strCategory;
    strTarget += '<w2:column width="110" style="" inputType="text" id="item" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="amount" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="remark" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" id="result" value=""' + fnResultAttr('body') + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="category">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="scol1" value="소계"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="scol3" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="scol4" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="scol5" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" id="scol6" value=""' + fnResultAttr('subTotal') + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="fcol1" value="합계"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="fcol2" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="fcol3" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="fcol4" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="fcol5" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" id="fcol6" value=""' + fnResultAttr('footer') + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 결과 확인 : con_area 로 고른 영역의 결과 Cell 표시값 출력 (Body 는 Row 별, SubTotal 은 그룹 순서별, Footer 는 1개)
//  - validation 1 : 영역을 바꿔 같은 계산식의 결과(또는 미계산)를 비교
//  - validation 2 ~ 12 : 선택한 계산식의 SubTotal 그룹별 / Footer 결과
//  - validation 13, 14 : con_condition 별 sumif / sumifs 결과
//  - 계산 결과는 화면에 그려진 값으로 판정하므로 Cell 의 표시 텍스트를 읽는다.
scwin.btn_result_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let cArea = con_area.getValue();
    if (cArea === "body") {
        for (let i = 0; i < dlt_bind.getRowCount(); i++) {
            let td = document.querySelector("td[id='" + target1.id + "_cell_" + i + "_5']");
            bottom.setReturnValue("Row " + i + " '" + td.textContent + "'");
        }
    } else if (cArea === "subTotal") {
        //  - SubTotal 표시 Row 외에 숨겨진 예비 Row 가 함께 렌더되므로 data-subtotalrowindex 속성이 있는 표시 Row 만 읽는다.
        let arrTd = target1.render.querySelectorAll("td[id='scol6']");
        let nSub = 0;
        for (let i = 0; i < arrTd.length; i++) {
            let tr = arrTd[i].parentNode;
            if (tr.getAttribute("data-subtotalrowindex") === null || tr.style.display === "none") continue;
            bottom.setReturnValue("SubTotal " + nSub + " '" + arrTd[i].textContent + "'");
            nSub++;
        }
    } else {
        let td = document.querySelector("td[id='" + target1.id + "_fcol6']");
        bottom.setReturnValue("Footer '" + td.textContent + "'");
    }
}
